class BowlingGame:
    def __init__(self):
        self.frames = []
        self.current = []

    def roll(self, pins):
        if pins < 0 or pins > 10:
            raise Exception("pins must be between 0 and 10")

        if len(self.frames) >= 10:
            raise Exception("cannot roll after the game is complete")

        if len(self.frames) < 9:
            self._roll_normal_frame(pins)
        else:
            self._roll_final_frame(pins)

    def _roll_normal_frame(self, pins):
        if not self.current:
            self.current.append(pins)
            if pins == 10:
                self._complete_frame()
        else:
            if self.current[0] + pins > 10:
                raise Exception("frame cannot score more than 10 points")
            self.current.append(pins)
            self._complete_frame()

    def _roll_final_frame(self, pins):
        first = self.current[0] if len(self.current) > 0 else None
        second = self.current[1] if len(self.current) > 1 else None

        if first is not None and second is not None:
            if first == 10 and second != 10 and second + pins > 10:
                raise Exception("frame cannot score more than 10 points")
            self.current.append(pins)
            self._complete_frame()
            return

        if second is not None:
            self.current.append(pins)
            return

        if first is not None and first != 10 and first + pins > 10:
            raise Exception("frame cannot score more than 10 points")

        self.current.append(pins)
        if first is not None and first != 10 and first + pins < 10:
            self._complete_frame()

    def _complete_frame(self):
        self.frames.append(self.current)
        self.current = []

    def score(self):
        if len(self.frames) < 10:
            raise Exception("game is not complete")

        rolls = []
        for frame in self.frames:
            rolls.extend(frame)

        total = 0
        index = 0
        for _ in range(10):
            if rolls[index] == 10:
                total += 10 + rolls[index + 1] + rolls[index + 2]
                index += 1
            elif rolls[index] + rolls[index + 1] == 10:
                total += 10 + rolls[index + 2]
                index += 2
            else:
                total += rolls[index] + rolls[index + 1]
                index += 2
        return total
